import { test, expect } from '@playwright/test';

test.describe('Async State Preservation During Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/async-state-page');
  });

  test('should preserve async state when navigating back to the same page', async ({ page }) => {
    // Set up async state
    await page.route('**/api/data', async (route) => {
      await route.abort();
    });

    // Fetch data
    const dataPromise = page.waitForResponse('**/api/data');
    await dataPromise;
    const data = await page.evaluate(() => JSON.parse(document.body.textContent));
    expect(data).toBeDefined();

    // Navigate to another page
    await page.goto('/another-page');

    // Navigate back to async state page
    await page.goto('/async-state-page');

    // Verify async state is preserved
    const preservedData = await page.evaluate(() => JSON.parse(document.body.textContent));
    expect(preservedData).toBeDefined();
    expect(preservedData).toEqual(data);
  });

  test('should preserve async state when navigating to a different page and then back', async ({ page }) => {
    // Set up async state
    await page.route('**/api/data', async (route) => {
      await route.abort();
    });

    // Fetch data
    const dataPromise = page.waitForResponse('**/api/data');
    await dataPromise;
    const data = await page.evaluate(() => JSON.parse(document.body.textContent));
    expect(data).toBeDefined();

    // Navigate to a different page
    await page.goto('/dashboard');

    // Navigate back to async state page
    await page.goto('/async-state-page');

    // Verify async state is preserved
    const preservedData = await page.evaluate(() => JSON.parse(document.body.textContent));
    expect(preservedData).toBeDefined();
    expect(preservedData).toEqual(data);
  });
});
